import{_ as t,o as r,c as o,a3 as i}from"./chunks/framework.CcKC9xfe.js";const m=JSON.parse('{"title":"Director configuration","description":"yarilo-director keeps the routing state of a cluster: which backend serves each user. Login pods ask it with a LOOKUP before they open a session to a…","frontmatter":{"outline":[2,4],"head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/architecture/director.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/architecture/director.html"}],["meta",{"property":"og:title","content":"Director configuration"}],["meta",{"name":"twitter:title","content":"Director configuration"}],["meta",{"property":"og:description","content":"yarilo-director keeps the routing state of a cluster: which backend serves each user. Login pods ask it with a LOOKUP before they open a session to a…"}],["meta",{"name":"twitter:description","content":"yarilo-director keeps the routing state of a cluster: which backend serves each user. Login pods ask it with a LOOKUP before they open a session to a…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/architecture/director.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/architecture/director.html\\",\\"headline\\":\\"Director configuration\\",\\"description\\":\\"yarilo-director keeps the routing state of a cluster: which backend serves each user. Login pods ask it with a LOOKUP before they open a session to a…\\",\\"dateModified\\":\\"2026-10-23T08:57:23.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/latest/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Director configuration\\",\\"item\\":\\"https://doc.yarilomail.org/latest/architecture/director.html\\"}]}]}"]]},"headers":[],"relativePath":"architecture/director.md","filePath":"architecture/director.md","lastUpdated":1792745843000}'),d={name:"architecture/director.md"};function a(s,e,n,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="director-configuration" tabindex="-1">Director configuration <a class="header-anchor" href="#director-configuration" aria-label="Permalink to &quot;Director configuration&quot;">​</a></h1><p><code>yarilo-director</code> keeps the routing state of a cluster: which backend serves each user. Login pods ask it with a <code>LOOKUP</code> before they open a session to a backend.</p><p>The director does not accept client connections. TLS, the PROXY protocol, XCLIENT and authentication all happen in the login pods; see <a href="/latest/installation/general.html">General settings</a> and <a href="/latest/installation/deployment.html">Deployment</a>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>A session reaches its backend in these steps:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mail client</span></span>\n<span class="line"><span>    │  IMAP / POP3 / Submission / ManageSieve / LMTP / JMAP</span></span>\n<span class="line"><span>    ▼</span></span>\n<span class="line"><span>login pod (imap-login, pop3-login, …)</span></span>\n<span class="line"><span>    │  1. TLS, PROXY header, authentication</span></span>\n<span class="line"><span>    │  2. LOOKUP &lt;user&gt; &lt;tag&gt;  ──────────►  yarilo-director</span></span>\n<span class="line"><span>    │                          ◄──────────  backend ip:port</span></span>\n<span class="line"><span>    │  3. dial the backend pod IP directly, send the preamble</span></span>\n<span class="line"><span>    ▼</span></span>\n<span class="line"><span>backend pod (yarilo-imap, yarilo-pop3, …)</span></span></code></pre></div><ul><li>The director answers from a consistent-hash ring of backends, weighted by <code>vhosts</code>, plus the sticky assignments it has already made.</li><li>Backends join the ring either from the static <code>mail_<wbr>servers</code> list or by registering themselves with a heartbeat.</li><li>With more than one replica, the directors form a ring of their own to share membership, the backend set and sticky assignments. See <a href="#ring-formation">Ring formation</a>.</li></ul><h2 id="listening-ports" tabindex="-1">Listening ports <a class="header-anchor" href="#listening-ports" aria-label="Permalink to &quot;Listening ports&quot;">​</a></h2><p>The director listens on three ports:</p><h3 id="director_service.listen" tabindex="-1"><code>listen</code> <a class="header-anchor" href="#director_service.listen" aria-label="Permalink to &quot;`listen` {#director_service.listen}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>:9102</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.director.directorPort</code></dd></dl></div><p>Address for <code>LOOKUP</code> from the login pods and for the ring protocol between directors. The chart takes a port number and renders <code>:&lt;port&gt;</code>.</p><h3 id="director_service.api.listen" tabindex="-1"><code>listen</code> <a class="header-anchor" href="#director_service.api.listen" aria-label="Permalink to &quot;`listen` {#director_service.api.listen}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>:9103</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.director.api.port</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.api.allowed_nets"><code>allowed_nets</code></a></dd></dl></div><p>Address of the admin API; see <a href="/latest/architecture/director_api.html">Director API</a>. The chart takes a port number.</p><h3 id="director_service.api.allowed_nets" tabindex="-1"><code>allowed_<wbr>nets</code> <a class="header-anchor" href="#director_service.api.allowed_nets" aria-label="Permalink to &quot;`allowed_nets` {#director_service.api.allowed_nets}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Helm</dt><dd><code>components.director.api.allowed_nets</code></dd></dl></div><p>CIDRs the admin API accepts requests from, on top of its token. Empty allows all.</p><h3 id="telemetry.listen" tabindex="-1"><code>listen</code> <a class="header-anchor" href="#telemetry.listen" aria-label="Permalink to &quot;`listen` {#telemetry.listen}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>:8080</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>telemetry.listen</code></dd></dl></div><p>Address of the Prometheus metrics and health endpoints.</p><p>Login pods reach the director through the ClusterIP <code>&lt;release&gt;-director</code> Service, set as each login component&#39;s <code>director_<wbr>addr</code>. The headless <code>&lt;release&gt;-director-ring</code> Service is for the ring only.</p><h2 id="director-service" tabindex="-1"><code>director_<wbr>service</code> <a class="header-anchor" href="#director-service" aria-label="Permalink to &quot;`director_service`&quot;">​</a></h2><p>These keys are the routing and lifecycle core. <code>user_<wbr>expire</code> and <code>backend_<wbr>expire</code> are described in <a href="/latest/installation/deployment.html#director_service.user_expire">Deployment</a>, with the other placement keys.</p><h3 id="director_service.ping_interval" tabindex="-1"><code>ping_<wbr>interval</code> <a class="header-anchor" href="#director_service.ping_interval" aria-label="Permalink to &quot;`ping_interval` {#director_service.ping_interval}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.ping_interval</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.ping_timeout"><code>ping_timeout</code></a></dd></dl></div><p>Keepalive pings to login pods and ring peers.</p><h3 id="director_service.ping_timeout" tabindex="-1"><code>ping_<wbr>timeout</code> <a class="header-anchor" href="#director_service.ping_timeout" aria-label="Permalink to &quot;`ping_timeout` {#director_service.ping_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.ping_timeout</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.ping_interval"><code>ping_interval</code></a></dd></dl></div><p>How long to wait for a <code>PONG</code> before the connection is closed.</p><h3 id="director_service.write_timeout" tabindex="-1"><code>write_<wbr>timeout</code> <a class="header-anchor" href="#director_service.write_timeout" aria-label="Permalink to &quot;`write_timeout` {#director_service.write_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.write_timeout</code></dd></dl></div><p>How long one push or reply write may take. <code>0</code> is no bound.</p><h3 id="director_service.shutdown.session_grace_period" tabindex="-1"><code>session_<wbr>grace_<wbr>period</code> <a class="header-anchor" href="#director_service.shutdown.session_grace_period" aria-label="Permalink to &quot;`session_grace_period` {#director_service.shutdown.session_grace_period}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.shutdown.session_grace_period</code></dd></dl></div><p>How long the director waits after <code>SIGTERM</code> before it exits. It leaves the ring gracefully in that time.</p><h3 id="director_service.peers" tabindex="-1"><code>peers</code> <a class="header-anchor" href="#director_service.peers" aria-label="Permalink to &quot;`peers` {#director_service.peers}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Helm</dt><dd><code>components.director.peers</code></dd></dl></div><p>Seeds for a one-time ring join. Empty with more than one replica, the chart seeds from the headless <code>-director-ring</code> Service.</p><h3 id="director_service.backend_unreachable_reporters" tabindex="-1"><code>backend_<wbr>unreachable_<wbr>reporters</code> <a class="header-anchor" href="#director_service.backend_unreachable_reporters" aria-label="Permalink to &quot;`backend_unreachable_reporters` {#director_service.backend_unreachable_reporters}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>2</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.backend_unreachable_reporters</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.backend_unreachable_window"><code>backend_unreachable_window</code></a></dd></dl></div><p>Distinct login pods that must report a backend unreachable before it is evicted early. A single-replica login fleet cannot give two, so set <code>1</code> there; the lease stays the backstop.</p><h3 id="director_service.backend_unreachable_window" tabindex="-1"><code>backend_<wbr>unreachable_<wbr>window</code> <a class="header-anchor" href="#director_service.backend_unreachable_window" aria-label="Permalink to &quot;`backend_unreachable_window` {#director_service.backend_unreachable_window}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>5</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.backend_unreachable_window</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.backend_unreachable_reporters"><code>backend_unreachable_reporters</code></a></dd></dl></div><p>The window those reports must arrive in.</p><h3 id="director_service.join_allowed_nets" tabindex="-1"><code>join_<wbr>allowed_<wbr>nets</code> <a class="header-anchor" href="#director_service.join_allowed_nets" aria-label="Permalink to &quot;`join_allowed_nets` {#director_service.join_allowed_nets}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Helm</dt><dd><code>components.director.join_allowed_nets</code></dd></dl></div><p>CIDRs a ring join is accepted from. Empty allows all.</p><h3 id="director_service.anti_entropy_interval" tabindex="-1"><code>anti_<wbr>entropy_<wbr>interval</code> <a class="header-anchor" href="#director_service.anti_entropy_interval" aria-label="Permalink to &quot;`anti_entropy_interval` {#director_service.anti_entropy_interval}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.anti_entropy_interval</code></dd></dl></div><p>Each director re-sends its member and tombstone list over every live ring connection this often, repairing a view that has diverged. <code>0</code> turns it off.</p><h3 id="director_service.tombstone_ttl" tabindex="-1"><code>tombstone_<wbr>ttl</code> <a class="header-anchor" href="#director_service.tombstone_ttl" aria-label="Permalink to &quot;`tombstone_ttl` {#director_service.tombstone_ttl}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>600</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.tombstone_ttl</code></dd></dl></div><p>How long a dead member&#39;s tombstone is kept. <code>0</code> keeps it for good.</p><p>The chart also renders <code>shutdown.<wbr>kill_<wbr>timeout</code>, but the director does not read it.</p><p>Backend eviction:</p><ul><li>A static backend from <code>mail_<wbr>servers</code>, or one added through the admin API, never heartbeats and never expires.</li><li>The last backend of a tag is never evicted, by either the lease or the reports; the director logs it instead.</li></ul><h2 id="director-service-mail-servers" tabindex="-1"><code>director_<wbr>service.<wbr>mail_<wbr>servers</code> <a class="header-anchor" href="#director-service-mail-servers" aria-label="Permalink to &quot;`director_service.mail_servers`&quot;">​</a></h2><p>This is the static backend list loaded at startup. Each <code>host</code> resolves to one or more pod IPs through DNS; a headless Service returns one A record per pod, and every IP joins the ring.</p><h3 id="director_service.mail_servers[].host" tabindex="-1"><code>host</code> <a class="header-anchor" href="#director_service.mail_servers[].host" aria-label="Permalink to &quot;`host` {#director_service.mail_servers[].host}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.director.backends[].host</code></dd></dl></div><p>Hostname of a static backend, typically a headless Service such as <code>yarilo-imap.<wbr>yarilo-backend.<wbr>svc.<wbr>cluster.<wbr>local</code>. Every IP it resolves to joins the ring.</p><h3 id="director_service.mail_servers[].port" tabindex="-1"><code>port</code> <a class="header-anchor" href="#director_service.mail_servers[].port" aria-label="Permalink to &quot;`port` {#director_service.mail_servers[].port}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.backends[].port</code></dd></dl></div><p>Backend port the login pod dials.</p><h3 id="director_service.mail_servers[].tag" tabindex="-1"><code>tag</code> <a class="header-anchor" href="#director_service.mail_servers[].tag" aria-label="Permalink to &quot;`tag` {#director_service.mail_servers[].tag}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.director.backends[].tag</code></dd></dl></div><p>Pool label. Empty is the default pool.</p><h3 id="director_service.mail_servers[].vhosts" tabindex="-1"><code>vhosts</code> <a class="header-anchor" href="#director_service.mail_servers[].vhosts" aria-label="Permalink to &quot;`vhosts` {#director_service.mail_servers[].vhosts}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>100</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.backends[].vhosts</code></dd></dl></div><p>Ring weight, <code>1</code> to <code>100</code>. <code>0</code> routes no users to the backend; under <code>assignment_<wbr>policy: least_<wbr>sessions</code> it drains.</p><p>Configure two static backends:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">director_service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yarilo-imap.yarilo-backend.svc.cluster.local</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">993</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yarilo-lmtp.yarilo-backend.svc.cluster.local</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><h2 id="mtls" tabindex="-1">mTLS <a class="header-anchor" href="#mtls" aria-label="Permalink to &quot;mTLS&quot;">​</a></h2><p>With <code>internal_<wbr>tls.<wbr>enabled: true</code>, the <code>director_<wbr>service.<wbr>listen</code> port requires a client certificate from everyone who connects: login pods sending <code>LOOKUP</code> and other directors on the ring.</p><p>Ring peers are dialled by pod IP, so the dial verifies a fixed server name, <code>ring_<wbr>tls_<wbr>server_<wbr>name</code>, which defaults to <code>&lt;release&gt;-director-ring</code>. That name must be a SAN in the director&#39;s certificate.</p><h3 id="director_service.ring_tls_server_name" tabindex="-1"><code>ring_<wbr>tls_<wbr>server_<wbr>name</code> <a class="header-anchor" href="#director_service.ring_tls_server_name" aria-label="Permalink to &quot;`ring_tls_server_name` {#director_service.ring_tls_server_name}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.director.internalTLS.ringTlsServerName</code></dd></dl></div><p>The name a ring dial verifies, since peers are dialled by pod IP. The chart sets <code>&lt;release&gt;-director-ring</code>, and the director&#39;s certificate must carry it as a SAN.</p><p>The certificate the chart makes for the <code>director</code> role carries it, along with <code>&lt;release&gt;-director</code> and the role SAN <code>director.<wbr>role.<wbr>yarilo.<wbr>internal</code>. With cert-manager, <code>components.<wbr>director.<wbr>internalTLS.<wbr>certificate.<wbr>enabled: true</code> renders the same names; a Secret of your own in <code>components.<wbr>director.<wbr>internalTLS.<wbr>secretName</code> must carry them too. The director port also checks the role per command: ring commands only from <code>director</code>, registration only from <code>backend-reg</code> (<a href="/latest/installation/deployment.html#peer-roles">Peer roles</a>).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>With internal TLS on and no ring name in the certificate, peers cannot verify each other and the ring never converges. The director logs an error when this happens.</p></div><h2 id="helm-values" tabindex="-1">Helm values <a class="header-anchor" href="#helm-values" aria-label="Permalink to &quot;Helm values&quot;">​</a></h2><p>All director settings live under <code>components.<wbr>director</code> in <code>helm/<wbr>values.<wbr>yaml</code>, and each card on this page names its chart value. Most keep the config key&#39;s name; the listen addresses take a port number (<code>directorPort</code>, <code>api.<wbr>port</code>), and the static backends are <code>backends[]</code>.</p><p>Run three replicas with one static backend:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    replicas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    backends</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yarilo-imap.yarilo-backend.svc.cluster.local</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">993</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        tag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>This setup:</p><ul><li>seeds the ring from the headless <code>-director-ring</code> Service, since <code>peers</code> is empty;</li><li>generates the ring secret and the API token into Secrets;</li><li>leaves client listeners to the login components, each pointing <code>director_<wbr>addr</code> at the <code>-director</code> Service.</li></ul><h2 id="placement-and-kick-pacing" tabindex="-1">Placement and kick pacing <a class="header-anchor" href="#placement-and-kick-pacing" aria-label="Permalink to &quot;Placement and kick pacing&quot;">​</a></h2><p>These keys are described in <a href="/latest/installation/deployment.html">Deployment</a>:</p><ul><li><a href="/latest/installation/deployment.html#director_service.assignment_policy"><code>assignment_<wbr>policy</code></a>: how a new user gets a backend;</li><li><a href="/latest/installation/deployment.html#director_service.director_domain_expire"><code>director_<wbr>domain_<wbr>expire</code></a> and the <a href="/latest/installation/deployment.html#director_service.director_domain_rebalance_percent">domain rebalance</a> settings, under <code>assignment_<wbr>policy: domain</code>;</li><li><a href="/latest/installation/deployment.html#director_service.user_kick_delay"><code>user_<wbr>kick_<wbr>delay</code></a>, <a href="/latest/installation/deployment.html#director_service.max_parallel_kicks"><code>max_<wbr>parallel_<wbr>kicks</code></a> and <a href="/latest/installation/deployment.html#director_service.max_parallel_moves"><code>max_<wbr>parallel_<wbr>moves</code></a>: kick pacing.</li></ul><h2 id="session-routing-sticky-assignments" tabindex="-1">Session routing &amp; sticky assignments <a class="header-anchor" href="#session-routing-sticky-assignments" aria-label="Permalink to &quot;Session routing &amp; sticky assignments&quot;">​</a></h2><p>Every login proxy (imap/pop3/submission/managesieve/lmtp) routes sessions one of two ways: <code>backend_<wbr>addr</code> (standalone, a fixed backend) or <code>director_<wbr>addr</code> (director mode, per-session <code>LOOKUP</code> via yarilo-director) — at least one is required, and <code>backend_<wbr>addr</code> wins when both are set, in all five components. <code>backend_<wbr>port</code> overrides the port a director <code>LOOKUP</code> returns when it differs from the backend&#39;s protocol-specific containerPort.</p><p><strong>Migration note:</strong> lmtp-login previously had the <em>opposite</em> precedence — <code>director_<wbr>addr</code> won when both were set. If your <code>lmtpLogin</code> Helm values set both <code>backend_<wbr>addr</code> and <code>director_<wbr>addr</code>, the login pod now logs a startup warning and silently switches from director routing to the static backend. Remove <code>backend_<wbr>addr</code> from <code>lmtpLogin</code> values to keep director routing.</p><p><code>director_<wbr>service.<wbr>username_<wbr>hash_<wbr>lowercase</code> (default <code>true</code>, Helm: <code>components.<wbr>director.<wbr>username_<wbr>hash_<wbr>lowercase</code>) lowercases usernames before they&#39;re hashed for ring routing or used as keys for sticky assignments and admin (<code>USER-MOVE</code>) overrides — without it, two spellings of the same account (<code>User@d.<wbr>test</code> / <code>user@d.<wbr>test</code>) can hash to different values and land on different backends, defeating sticky routing. Migration note: enabling this on an already-running cluster changes hashes for mixed-case usernames — their existing sticky entries just expire naturally via <code>user_<wbr>expire</code>, no special migration step is needed.</p><blockquote><p><strong>Sharing mailboxes between users of a domain?</strong> Set <code>assignment_<wbr>policy: domain</code>: a domain is placed on the backend with the fewest connections and every user of it follows, with no hash template to get right. A user&#39;s sticky entry holds only while it names the domain&#39;s backend: after a move, users who logged in before it follow at their next login instead of riding their entry to the old backend. The older pairing below still works and stays supported.</p><p><strong>The older pairing:</strong> set <code>username_<wbr>hash: &quot;%Ld&quot;</code><strong>and</strong> <code>assignment_<wbr>policy: hash</code>. The default hashes the whole address, so users of one domain land on different backends — harmless where those backends share one PV, fatal where each has its own storage. And <code>least_<wbr>sessions</code> never reads the username at all, so it silently defeats the hash template. See <a href="/latest/storage/owner_shared_ns.html#routing-within-a-farm-users-who-share-must-land-on-one-backend">Owner/shared namespaces</a>.</p></blockquote><p><code>director_<wbr>service.<wbr>username_<wbr>hash</code> (default <code>&quot;&quot;</code>, Helm: <code>components.<wbr>director.<wbr>username_<wbr>hash</code>) is the username→hash-key template, which uses the reference&#39;s username-hash expression syntax, so an existing template migrates <strong>verbatim</strong> — <code>%Lu</code> stays <code>%Lu</code>. Supported variables: <code>%u</code> (whole username), <code>%n</code> (local part, before the first <code>@</code>), <code>%d</code> (domain, after the first <code>@</code>), each with an optional <code>%L</code> lowercase modifier, plus <code>%%</code> for a literal percent. This is a real routing lever, not just config parity: <code>%Ld</code> hashes on the <strong>domain only</strong> so a whole domain (and its shared mailboxes/ACLs) lands on one backend, and <code>%Ln</code> hashes on the local part only for alias-domain installs. A domain-less username follows the reference semantics — <code>%n</code> is the whole username, <code>%d</code> is empty (so a <code>%d</code> template routes every domain-less account to one backend). When <code>username_<wbr>hash</code> is set it — not <code>username_<wbr>hash_<wbr>lowercase</code> — governs case-folding (the ingress no longer pre-lowercases, so <code>%u</code> is truly case-sensitive), and the <code>USER-KICKED</code> payload keeps the session&#39;s original-case username so login-side kick matching still lands. An empty value derives the template from <code>username_<wbr>hash_<wbr>lowercase</code> (<code>%Lu</code> / <code>%u</code>) for byte-identical back-compat with clusters that predate <code>username_<wbr>hash</code>. An invalid template aborts director startup. (yarilo&#39;s uint32 fold is little-endian — deliberately not byte-compatible with the reference&#39;s ring, a scenario our architecture never produces; we borrow the routing semantics, not the byte layout.)</p><p><strong><code>%d</code> domain-hash — read before you use it.</strong> The hash is applied <strong>within a tag</strong>, not globally: every <code>LOOKUP</code> carries a per-user tag (tag = NFS shard) and the ring is tag-scoped (<code>LookupBackendByTag</code>), exactly like the reference&#39;s per-tag lookup. So a <code>%Ld</code> template routes a domain to <strong>one backend per tag</strong> — if the domain&#39;s mailboxes are spread across tags (the tag is assigned per user by userdb, independent of the hash), those users land on different tag rings and different backends; <code>%d</code> does <strong>not</strong> collapse a multi-tag domain onto a single host. The failure mode to avoid is putting one large domain entirely in <strong>one</strong> tag: there <code>%Ld</code> pins the whole domain to a single backend with <strong>no load rebalancing</strong> (yarilo, like the reference, distributes only by consistent hashing + vhost capacity weighting; it never auto-spreads a hot key). The cure is spreading the domain across tags via userdb, not changing the hash. Use <code>%Ld</code> only when a domain&#39;s shared mailboxes/ACLs genuinely must be storage-local within a tag.</p><p><strong>Backend evacuation — graceful vs force.</strong> <code>yarctl director backends flush &lt;ip|all&gt;</code> drains a backend. By default the drain is <strong>graceful and throttled</strong>: the host is taken out of the ring and its users are migrated in a self-clocked window of at most <code>director_<wbr>service.<wbr>max_<wbr>parallel_<wbr>moves</code> (default <code>5</code>, Helm: <code>components.<wbr>director.<wbr>max_<wbr>parallel_<wbr>moves</code>) confirmed-kills — each user&#39;s old sessions must confirm gone before the next user is pulled in, so a planned drain (rolling upgrade, maintenance) spreads the re-login across the surviving pods instead of stampeding them all at once. <code>--force</code> kicks every session immediately; <code>--max-parallel N</code> overrides the window for one run. Re-login is deterministic without a proactive pin move: the evacuating host is already excluded from the ring, so a kicked user&#39;s re-<code>LOOKUP</code> rehashes to the same surviving backend it would have been moved to, and the confirmed-kill hold makes that re-<code>LOOKUP</code> wait until the old session is gone (no split-writer window). The drain is orchestrated by the single director that receives the request; if that director is lost mid-drain the operator re-runs <code>flush</code> (drain-state is not replicated across directors — matching the reference, where the originating director drives the drain). Matches the reference&#39;s forced-flush and max-parallel drain behaviour.</p><p><strong>Per-user flush hook.</strong> <code>director_<wbr>service.<wbr>flush_<wbr>program</code> (default <code>&quot;&quot;</code> = disabled, Helm: <code>components.<wbr>director.<wbr>flush_<wbr>program</code>) is an optional external executable run once per user <strong>after</strong> a deliberate relocation — an admin <code>USER-MOVE</code> or a graceful evacuation — has been confirmed ring-wide, i.e. after that user&#39;s old sessions are gone. Operators hook mailbox-cache flush, external session cleanup, metrics, etc. It is called as <code>flush_<wbr>program FLUSH &lt;username&gt; &lt;username_<wbr>hash&gt; &lt;old_<wbr>backend&gt; &lt;new_<wbr>backend&gt;</code> (<code>new_<wbr>backend</code> is empty when the user was kicked with no surviving backend to land on). It is <strong>best-effort and asynchronous</strong> with a bounded timeout: a slow or failing hook is logged and never blocks the ring/<code>LOOKUP</code> path or fails the move (the routing change already committed). The bound is <code>director_<wbr>service.<wbr>flush_<wbr>program_<wbr>timeout</code> (seconds, default <code>10</code>, Helm: <code>components.<wbr>director.<wbr>flush_<wbr>program_<wbr>timeout</code>); <code>0</code> selects the default rather than disabling the bound. Raise it for a hook that legitimately takes longer — and note what best-effort means for diagnosing one: a run that exceeds the bound is killed, and the only trace is a <code>WARN</code> on the director (<code>flush hook failed (best-effort, move already committed)</code> with <code>err=&quot;signal: killed&quot;</code>). Nothing surfaces on the hook&#39;s own side, so a script that always overruns simply never completes, silently, until someone reads the director&#39;s log. Only the director that <strong>originated</strong> the move runs it — mass/reactive paths (<code>backend-down</code> auto-kick, <code>--force</code> flush) deliberately do not trigger it, and a move that creates a fresh pin with no prior host is skipped. The hook runs at the same point as the reference&#39;s flush hook, after the ring-wide <code>USER-KILLED-EVERYWHERE</code>; the program runs in the director pod&#39;s context, <code>exec.<wbr>Command</code> only (no fork). A unix-socket hook variant is a possible future follow-up. An <strong>offline</strong> user — one with no active sessions when the move starts — confirms after <code>user_<wbr>kill_<wbr>confirm_<wbr>grace</code> (~1s) instead of waiting out <code>user_<wbr>kill_<wbr>timeout</code>, so the hook fires promptly for the common admin case of moving a user who isn&#39;t currently connected; a user with live sessions still confirms only once those sessions have drained.</p><h3 id="tag-sharding-models" tabindex="-1">Tag sharding models <a class="header-anchor" href="#tag-sharding-models" aria-label="Permalink to &quot;Tag sharding models&quot;">​</a></h3><p>Every director <code>LOOKUP</code> carries a mandatory tag field — there is no full-ring mode: <code>&quot;&quot;</code> selects the untagged backend pool, not &quot;any tag.&quot; Two sharding models are supported:</p><ul><li><strong>Static (dedicated login fleet per tag pool).</strong> Each login component&#39;s <code>director_<wbr>tag</code> (Helm: <code>components.<wbr>&lt;login&gt;.<wbr>director_<wbr>tag</code>, e.g. <code>components.<wbr>imapLogin.<wbr>director_<wbr>tag</code>) restricts that component&#39;s lookups to one tag-pool — set this when running a dedicated login Deployment per tag pool, per the tag-based sharding model in <a href="/latest/installation/deployment.html">Deployment</a>. In a deployment with no tags configured at all, every backend is untagged, so the default <code>director_<wbr>tag: &quot;&quot;</code> behaves exactly like the old (buggy) full-ring lookup — untagged/standalone deployments see no behavior change.</li><li><strong>Shared (per-user tag from passdb/userdb).</strong> One login fleet serving users of every tag-pool: a <code>director_<wbr>tag</code> extra field on the passdb or userdb response (SQL: an ordinary column in <code>passdb_<wbr>sql_<wbr>query</code>/<code>userdb_<wbr>sql_<wbr>query</code>, same generic column-forwarding as <code>allow_<wbr>nets</code> — no driver code change needed) picks the tag for that one user&#39;s <code>LOOKUP</code>, overriding the component&#39;s static <code>director_<wbr>tag</code>. IMAP/POP3/Submission/ManageSieve pick it up from the AUTH response; LMTP resolves it with a per-recipient userdb lookup before the director <code>LOOKUP</code>. A user with no <code>director_<wbr>tag</code> field falls back to the component&#39;s static value.</li></ul><h2 id="ring-formation" tabindex="-1">Ring formation <a class="header-anchor" href="#ring-formation" aria-label="Permalink to &quot;Ring formation&quot;">​</a></h2><p>Director replicas form a ring on their own. Members are ordered by IP and port, and each one dials only its right neighbour, never every other member. Any member count serves requests, and a single director is a ring of one.</p><h3 id="joining-the-ring" tabindex="-1">Joining the ring <a class="header-anchor" href="#joining-the-ring" aria-label="Permalink to &quot;Joining the ring&quot;">​</a></h3><p><code>components.<wbr>director.<wbr>peers</code> is a list of seeds. A new director sends <code>DIRECTOR-JOIN</code> to them, and membership then spreads around the ring.</p><p>Left empty with more than one replica, the seed is the headless <code>&lt;release&gt;-director-ring:9102</code> Service. Each cycle the seed name is resolved and every address but the director&#39;s own is polled. The ClusterIP <code>&lt;release&gt;-director</code> Service is only for the login pods&#39; <code>LOOKUP</code>: as a seed it would load-balance, and a director could dial itself.</p><p>The seed is polled every <code>seed_<wbr>poll_<wbr>interval</code> seconds (default <code>2</code>; a negative value polls once). Once the ring holds <code>min_<wbr>members</code> directors (default <code>3</code>), the interval becomes <code>seed_<wbr>poll_<wbr>idle_<wbr>interval</code> (default <code>2</code>). Raising it saves polling, and a dead member is evicted more slowly.</p><p><code>components.<wbr>director.<wbr>ring_<wbr>secret</code> (generated into the Secret <code>&lt;release&gt;-director-ring-secret</code>) authenticates every join and every ring connection. Without it a director never joins and runs alone. When <code>join_<wbr>allowed_<wbr>nets</code> is set, only those addresses may join. Every director must run a release that speaks the same join proof, so a ring being upgraded re-forms once the rollout completes.</p><h4 id="director_service.seed_poll_interval" tabindex="-1"><code>seed_<wbr>poll_<wbr>interval</code> <a class="header-anchor" href="#director_service.seed_poll_interval" aria-label="Permalink to &quot;`seed_poll_interval` {#director_service.seed_poll_interval}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>2</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.seed_poll_interval</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.seed_poll_idle_interval"><code>seed_poll_idle_interval</code></a> <a href="/latest/architecture/director.html#director_service.min_members"><code>min_members</code></a></dd></dl></div><p>How often the seed is polled while the ring is below <code>min_<wbr>members</code>. A negative value polls once.</p><h4 id="director_service.seed_poll_idle_interval" tabindex="-1"><code>seed_<wbr>poll_<wbr>idle_<wbr>interval</code> <a class="header-anchor" href="#director_service.seed_poll_idle_interval" aria-label="Permalink to &quot;`seed_poll_idle_interval` {#director_service.seed_poll_idle_interval}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>2</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.seed_poll_idle_interval</code></dd><dt>See also</dt><dd><a href="/latest/architecture/director.html#director_service.seed_poll_interval"><code>seed_poll_interval</code></a></dd></dl></div><p>The poll interval once the ring holds <code>min_<wbr>members</code>. Raising it saves polling, and a dead member is evicted more slowly.</p><h4 id="director_service.min_members" tabindex="-1"><code>min_<wbr>members</code> <a class="header-anchor" href="#director_service.min_members" aria-label="Permalink to &quot;`min_members` {#director_service.min_members}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.min_members</code></dd></dl></div><p>The ring size the seed polling aims for. Below it, the director polls at <code>seed_<wbr>poll_<wbr>interval</code>.</p><h4 id="director_service.ring_secret" tabindex="-1"><code>ring_<wbr>secret</code> <a class="header-anchor" href="#director_service.ring_secret" aria-label="Permalink to &quot;`ring_secret` {#director_service.ring_secret}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.director.ring_secret</code></dd></dl></div><p>Authenticates every join and every ring connection. Without it a director never joins and runs alone. The chart generates it into the Secret <code>&lt;release&gt;-director-ring-secret</code>.</p><h3 id="keeping-the-view-consistent" tabindex="-1">Keeping the view consistent <a class="header-anchor" href="#keeping-the-view-consistent" aria-label="Permalink to &quot;Keeping the view consistent&quot;">​</a></h3><ul><li>Every ring connection exchanges the member list and the list of removed members (tombstones).</li><li>Every <code>anti_<wbr>entropy_<wbr>interval</code> seconds (default <code>3</code>), each director re-sends its view over every live ring connection. This repairs a view that has diverged.</li><li>A tombstone expires after <code>tombstone_<wbr>ttl</code> seconds (default <code>600</code>).</li><li>An event is forwarded over every live ring connection except the one it came in on.</li></ul><h3 id="detecting-a-dead-member" tabindex="-1">Detecting a dead member <a class="header-anchor" href="#detecting-a-dead-member" aria-label="Permalink to &quot;Detecting a dead member&quot;">​</a></h3><ul><li>Both neighbours of a director watch it: the right side through its dial, the left side through the connection it accepted. A few short probes confirm a loss before it is declared.</li><li>Each ring connection exchanges <code>PING</code>/<code>PONG</code> every <code>ping_<wbr>interval</code> seconds (default <code>30</code>). A peer silent for <code>ping_<wbr>interval + ping_<wbr>timeout</code> (default <code>10</code>) counts as lost.</li><li>A director that closes a connection on purpose says why with <code>QUIT</code>, so the other end does not mistake it for a death.</li><li>On SIGTERM a director announces its own removal, sends <code>QUIT</code> on every ring connection and refuses new joins. A director killed outright is detected by its neighbours.</li></ul><h3 id="sharing-sticky-assignments" tabindex="-1">Sharing sticky assignments <a class="header-anchor" href="#sharing-sticky-assignments" aria-label="Permalink to &quot;Sharing sticky assignments&quot;">​</a></h3><p>On every ring connection a director sends its sticky user assignments, so a restarted director starts with the cluster&#39;s routing state, not an empty one. A new assignment made by a <code>LOOKUP</code> travels around the ring as <code>USER-ASSIGN</code>.</p><p>Assignments are ordered by a logical clock, not by wall time: the higher sequence wins, and a tie goes to the lower director id. When a merge moves a user to another backend, the director whose assignment lost kicks that user&#39;s sessions on the old backend, so one mailbox is never served by two backends.</p>',128)])])}const g=t(d,[["render",a]]);export{m as __pageData,g as default};
